# roman_to_int :: 'I'
def roman_to_int(s):
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for c in reversed(s):
        v = vals[c]
        total += -v if v < prev else v
        prev = v
    return total

if __name__ == '__main__':
    print(roman_to_int('I'))

